# Verbes à l'impératif « tu » → « vous » (le traducteur comprend mieux « Faites gratiner » que « Fais gratiner »)
VERBS = {"fais": "faites", "sers": "servez", "mets": "mettez", "remets": "remettez", "cuis": "cuisez", "bats": "battez", "couvre": "couvrez", "recouvre": "recouvrez",
 "garnis": "garnissez", "farcis": "farcissez", "refroidis": "refroidissez", "pétris": "pétrissez", "remplis": "remplissez", "réunis": "réunissez", "prends": "prenez", "fonds": "faites fondre",
 "dore": "faites dorer", "gratine": "faites gratiner"}
for v in ("ajoute mélange verse coupe émince épluche arrose égoutte mixe laisse enfourne dispose étale parsème assaisonne rectifie porte poêle saupoudre incorpore fouette monte forme roule "
          "ficelle préchauffe remue réserve presse râpe lave rince écrase hache nappe poche prépare retire retourne goûte décore plonge filtre chauffe réchauffe badigeonne alterne tartine trempe "
          "compte vérifie découpe partage enroule plie ferme dépose casse sépare travaille abaisse écale arrose détaille glisse coupe-les sale mouille déglace fais-les termine sers-les "
          "décortique lie ajuste pose tranche émiette répartis égrène").split():
    if v not in VERBS and "-" not in v:
        VERBS[v] = (v[:-1] + "ssez") if v.endswith("is") else v + "z"
